export function startOfLocalDayBefore(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const { year, month, day } = zoneParts(reference, timeZone);
  return toIsoTimestamp(zonedWallTimeToUtc(year, month - 1, day - days, 0, timeZone));
